631	        pet.getType().setName(null);
632	        this.clinicService.savePet(pet);
633	        PetDto petDto = petMapper.toPetDto(pet);
634	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
635	            .buildAndExpand(pet.getId()).toUri());
636	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
637	    }
638	
639	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
640	    @Override
641	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
642	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
643	        if (currentOwner != null) {
644	            Pet currentPet = this.clinicService.findPetById(petId);
645	            if (currentPet != null) {
646	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
647	                currentPet.setName(petFieldsDto.getName());
648	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
649	                this.clinicService.savePet(currentPet);
650	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
651	            }
652	        }
653	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
654	    }
655	
656	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
657	    @Override
658	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
659	        HttpHeaders headers = new HttpHeaders();
660	        Visit visit = visitMapper.toVisit(visitFieldsDto);
661	        Pet pet = new Pet();
662	        pet.setId(petId);
663	        visit.setPet(pet);
664	        this.clinicService.saveVisit(visit);
665	        VisitDto visitDto = visitMapper.toVisitDto(visit);
666	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
667	            .buildAndExpand(visit.getId()).toUri());
668	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
669	    }
670	
